import numpy as np
import matplotlib.pyplot as plt
import base64, zlib

# Original: https://wiki.math.ntnu.no/_media/imax3011/2025h/mm.gif
# Gråtoner, skalert til 96 x 96 for korte beregninger i nettleseren.
_portrait_data = ""
portrait = np.frombuffer(zlib.decompress(base64.b64decode(_portrait_data)), dtype=np.uint8).reshape(96,96).astype(float)/255

# Like bildedimensjoner gjør parameterbudsjettet sammenlignbart på tvers av mønstre.
def challenge_images():
    n = 96
    text = np.zeros((n,n))
    # Fire enkle bokstavformer: H, I, L, I; ingen skrifttypeavhengighet.
    for col in (8, 30, 52, 74):
        text[24:72, col:col+5] = 1
    text[24:72, 20:25] = 1
    text[46:51, 8:25] = 1
    text[67:72, 52:69] = 1
    return {'portrett': portrait.copy(), 'tekst': text,
            'diagonal': np.eye(n),
            'tilfeldig': np.random.default_rng(7).random((n,n))}

# Samme gråtoneskala i alle bilder; visning endrer ikke matrisene brukt til feilberegning.
def show_images(images):
    fig, axes = plt.subplots(1, len(images), figsize=(3*len(images),3), squeeze=False)
    for ax, (name, value) in zip(axes[0], images.items()):
        ax.imshow(value, cmap='gray', vmin=0, vmax=1)
        ax.set_title(name); ax.axis('off')
    plt.tight_layout(); plt.show()

# Visningshjelper: behold k SVD-ledd. I prosjektet implementeres egen truncate-funksjon.
def rank_image(A, k):
    U, s, Vt = np.linalg.svd(A, full_matrices=False)
    return (U[:, :k]*s[:k]) @ Vt[:k, :]

# Lag kjent signal, uskarpe data og én støyrealisasjon for et kontrollert inversjonsforsøk.
def blur_problem(noise_level=.005, seed=17):
    n = 80
    t = np.linspace(0, 1, n)
    truth = ((t>.2)&(t<.4)).astype(float) + .6*np.exp(-((t-.72)/.06)**2)
    # Hver rad beskriver hvordan en måling blander signalverdier fra nærliggende posisjoner.
    H = np.exp(-.5*((t[:,None]-t[None,:])/.035)**2)
    # Radsum 1 gjør at et konstant signal forblir konstant etter glatting.
    H /= H.sum(axis=1, keepdims=True)
    # Dette er feilfrie målinger; støyen legges til etter at signalet er glattet.
    clean = H @ truth
    observed = clean + noise_level*np.random.default_rng(seed).standard_normal(n)
    return t, H, truth, clean, observed
